--
-- Table structure for table `data_staff`
--

DROP TABLE IF EXISTS `data_staff`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `data_staff` (
  `id_staff` int(11) NOT NULL AUTO_INCREMENT,
  `nama` varchar(200) DEFAULT NULL,
  `nip` varchar(50) DEFAULT NULL,
  `bidang` varchar(100) DEFAULT NULL,
  `nuptk` varchar(50) DEFAULT NULL,
  `tempat_lahir` varchar(50) DEFAULT NULL,
  `tanggal_lahir` varchar(50) DEFAULT NULL,
  `jenis_kelamin` varchar(50) DEFAULT NULL,
  `nama_ibu` varchar(50) DEFAULT NULL,
  `jabatan` varchar(50) DEFAULT NULL,
  `golongan_capeg` varchar(50) DEFAULT NULL,
  `tmt_capeg` varchar(50) DEFAULT NULL,
  `golongan_akhir` varchar(50) DEFAULT NULL,
  `tmt_akhir` varchar(50) DEFAULT NULL,
  `masa_kerjath` int(50) DEFAULT NULL,
  `masa_kerjabln` int(50) DEFAULT NULL,
  `mulai_tugas` varchar(50) DEFAULT NULL,
  `tingkat_ijazah` varchar(50) DEFAULT NULL,
  `jurusan_kuliah` varchar(50) DEFAULT NULL,
  `tahun_tamat` int(50) DEFAULT NULL,
  `keterangan` varchar(200) DEFAULT NULL,
  `foto` longblob DEFAULT NULL,
  PRIMARY KEY (`id_staff`)
) ENGINE=InnoDB AUTO_INCREMENT=25 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `data_staff`
--

